func writeSemanticParseCacheArtifact(generationDir, path, blob, contentHash string) (string, error) {
	key := contentHash
	if key == "" {
		sum := sha256.Sum256([]byte(path + "\x00" + blob))
		key = "sha256:" + hex.EncodeToString(sum[:])
	}
	if !strings.HasPrefix(key, "sha256:") {
