	for _, file := range files {
		wanted[file] = struct{}{}
	}
	f, err := os.Open(snapshotPath)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	scanner := newSemanticScanner(f)
	first := true
	var symbols []semanticRecord
	for scanner.Scan() {
		if first {
